mapper.select:
select
t1.id,t1.card_id,t1.subsidy_type,t1.subsidy_date, t1.money,t2.`name` as userName ,t3.file_name as fileName
from poor_subsidy t1
left join poor_user t2 on t1.card_id=t2.card_id
left join poor_data_file t3 on t1.data_file_id=t3.id

    and t1.card_id like concat('%', #{cardId}, '%')
    and t1.subsidy_type = #{subsidyType}
    and YEAR(t1.subsidy_date) = #{year}
    and t1.data_file_id =#{fileId}
    and t2.id is null
